Function message <- WhatToShow(code As Integer, rate As Integer)
  Define message As String;
  If code = 200 Then
    message <- "Price: " + toText(2 * rate);
  Else
    message <- "Service unavailable (" + toText(code) + ")";
  EndIf
EndFunction

Algorithm WhatToDo
  Define code As Integer;
  Define rate As Integer;
  Read code;
  Read rate;
  Write WhatToShow(code, rate);
EndAlgorithm
